import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Bar, BarChart, CartesianGrid, Cell, ComposedChart, Legend, Line, LineChart, ResponsiveContainer, Scatter, ScatterChart, Tooltip, XAxis, YAxis, ZAxis } from 'recharts';
import { FileSpreadsheet, Loader2, Plus, Target, TrendingUp, Upload, X } from 'lucide-react';
import { Button, Card, CardContent, CardHeader, CardTitle, Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, Input, Label } from '@/src/components/ui';
import { useAuth } from '../auth/AuthContext';
import { repository } from '../shared/AgronomicRepository';
import { useCatalogs } from '../shared/useCatalogs';
import { parseProductivityFile } from '../shared/spreadsheetImport';
import { displayZoneName, normalizeLotCode, normalizeZoneName } from '../cycles/cycleLogic';
import type { CycleExecution, CycleLaborRule, ProductivityImport, ProductivityProjection, ProductivityProjectionScope, ProductivityRecord } from '../types';

type View = 'resumen' | 'tendencias' | 'rendimiento' | 'desempeno' | 'lotes' | 'proyecciones';
type RangeMode = 'MENSUAL' | 'ANUAL';

const numberFormatter = new Intl.NumberFormat('es-CO', { maximumFractionDigits: 1 });
const percentageFormatter = new Intl.NumberFormat('es-CO', { maximumFractionDigits: 1, signDisplay: 'always' });
const MONTHS = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];
const PALETTE = ['#315D43', '#80a832', '#f59e0b', '#0f766e', '#7c3aed', '#dc2626', '#0369a1', '#a16207'];

function currentPeriod() { return new Date().toLocaleDateString('en-CA', { timeZone: 'America/Bogota' }).slice(0, 7); }
function toNumberOrNull(value: string) { const parsed = Number(value.replace(',', '.')); return value.trim() && Number.isFinite(parsed) ? parsed : null; }
function tonsOf(record: ProductivityRecord) { return record.tons ?? (record.kilograms === null ? 0 : record.kilograms / 1000); }
function recordZone(record: ProductivityRecord, locations: Map<string, any>) { return normalizeZoneName(record.zonaSnapshot || locations.get(record.loteCode)?.zone || 'Sin zona'); }
function recordSiembra(record: ProductivityRecord, locations: Map<string, any>) { const value = record.siembraSnapshot ?? locations.get(record.loteCode)?.anoSiembra; return value === null || value === undefined || value === '' ? 'Sin siembra' : String(value); }
function formatPeriod(period: string) { const [year, month] = period.split('-'); return `${MONTHS[Math.max(0, Number(month) - 1)] || month} ${year}`; }

function metricSummary(records: ProductivityRecord[], locations: Map<string, any>) {
  const lotCodes = new Set(records.map((record) => record.loteCode));
  const tons = records.reduce((sum, record) => sum + tonsOf(record), 0);
  const kilograms = records.reduce((sum, record) => sum + (record.kilograms || 0), 0);
  const racimos = records.reduce((sum, record) => sum + (record.racimos || 0), 0);
  const lots = [...lotCodes].map((code) => locations.get(code)).filter(Boolean);
  const hectares = lots.reduce((sum, lot) => sum + (Number(lot.ha) || 0), 0);
  // Los racimos pertenecen a todo el lote. Las palmas diferenciadas son solo
  // las que reciben manejo especial por ronda hídrica y no representan su total.
  const palms = lots.reduce((sum, lot) => sum + (Number(lot.palmasTotales ?? lot.palmas_totales) || 0), 0);
  const weightValues = records.map((record) => record.averageWeight).filter((value): value is number => value !== null);
  return { tons, kilograms, racimos, lotCount: lotCodes.size, hectares, palms, tonsPerHectare: hectares ? tons / hectares : null, averageWeight: kilograms && racimos ? kilograms / racimos : weightValues.length ? weightValues.reduce((sum, value) => sum + value, 0) / weightValues.length : null, bunchesPerPalm: palms && racimos ? racimos / palms : null };
}

function aggregate(records: ProductivityRecord[], keyFor: (record: ProductivityRecord) => string, locations: Map<string, any>) {
  const groups = new Map<string, ProductivityRecord[]>();
  records.forEach((record) => { const key = keyFor(record); groups.set(key, [...(groups.get(key) || []), record]); });
  return Array.from(groups.entries()).map(([name, rows]) => ({ name, ...metricSummary(rows, locations) }));
}

function Empty({ message }: { message: string }) { return <div className="h-full min-h-44 flex items-center justify-center text-center text-sm text-gray-400 px-8">{message}</div>; }
function ChartCard({ title, description, children, className = '' }: { title: string; description?: string; children: React.ReactNode; className?: string }) { return <Card className={`shadow-sm ${className}`}><CardHeader className="pb-2"><CardTitle className="text-base text-forest-950">{title}</CardTitle>{description && <p className="text-xs text-gray-500 mt-1">{description}</p>}</CardHeader><CardContent><div className="h-[300px]">{children}</div></CardContent></Card>; }
function Metric({ label, value, suffix, note }: { label: string; value: string; suffix: string; note?: string }) { return <Card className="shadow-sm"><CardContent className="p-4"><p className="text-2xl font-black text-forest-950">{value} <span className="text-sm text-gray-500">{suffix}</span></p><p className="mt-1 text-xs font-bold uppercase tracking-wide text-gray-500">{label}</p>{note && <p className="mt-1 text-[11px] text-gray-400">{note}</p>}</CardContent></Card>; }
function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="space-y-1.5"><Label>{label}</Label>{children}</label>; }

export default function Productivity() {
  const { user } = useAuth();
  const { catalogs } = useCatalogs();
  const [records, setRecords] = useState<ProductivityRecord[]>([]);
  const [imports, setImports] = useState<ProductivityImport[]>([]);
  const [projections, setProjections] = useState<ProductivityProjection[]>([]);
  const [cycleExecutions, setCycleExecutions] = useState<CycleExecution[]>([]);
  const [cycleRules, setCycleRules] = useState<CycleLaborRule[]>([]);
  const [loading, setLoading] = useState(true);
  const [view, setView] = useState<View>('resumen');
  const [rangeMode, setRangeMode] = useState<RangeMode>('MENSUAL');
  const [period, setPeriod] = useState(currentPeriod());
  const [year, setYear] = useState(currentPeriod().slice(0, 4));
  const [compareYear, setCompareYear] = useState('SIN_COMPARACION');
  const [zone, setZone] = useState('TODAS');
  const [siembra, setSiembra] = useState('TODAS');
  const [selectedLot, setSelectedLot] = useState('');
  const [projectionFocus, setProjectionFocus] = useState<'FILTROS' | 'LOTE'>('FILTROS');
  const [preview, setPreview] = useState<Awaited<ReturnType<typeof parseProductivityFile>> & { file: File } | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [importing, setImporting] = useState(false);
  const [manualOpen, setManualOpen] = useState(false);
  const [projectionOpen, setProjectionOpen] = useState(false);
  const [manual, setManual] = useState({ period: currentPeriod(), loteCode: '', racimos: '', kilograms: '', tons: '', averageWeight: '' });
  const [projectionForm, setProjectionForm] = useState<{ period: string; scope: ProductivityProjectionScope; scopeValue: string; projectedTons: string }>({ period: currentPeriod(), scope: 'GLOBAL', scopeValue: 'GLOBAL', projectedTons: '' });
  const [saving, setSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubscribe = repository.subscribeProductivity((next) => { setRecords(next.records); setImports(next.imports); setProjections(next.projections); setLoading(false); });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const unsubscribe = repository.subscribeCycles((next) => {
      setCycleExecutions(next.executions);
      setCycleRules(next.rules);
    });
    return () => unsubscribe();
  }, []);

  const locations = useMemo(() => new Map((catalogs.locations || []).map((location: any) => [normalizeLotCode(location.name), location])), [catalogs.locations]);
  const zones = useMemo(() => Array.from(new Set([...((catalogs.locations || []).map((location: any) => normalizeZoneName(location.zone))), ...records.map((record) => normalizeZoneName(record.zonaSnapshot))].filter(Boolean) as string[])).sort(), [catalogs.locations, records]);
  const siembras = useMemo(() => Array.from(new Set([...((catalogs.locations || []).map((location: any) => location.anoSiembra)), ...records.map((record) => record.siembraSnapshot)].filter((value) => value !== null && value !== undefined).map(String))).sort((a, b) => Number(a) - Number(b)), [catalogs.locations, records]);
  const years = useMemo(() => Array.from(new Set(records.map((record) => record.period.slice(0, 4)))).sort((a, b) => Number(b) - Number(a)), [records]);

  useEffect(() => {
    if (!records.length) return;
    const latest = [...records].sort((a, b) => b.period.localeCompare(a.period))[0]?.period;
    if (latest && !records.some((record) => record.period === period)) setPeriod(latest);
    if (latest && !years.includes(year)) setYear(latest.slice(0, 4));
  }, [records, period, year, years]);

  const baseRecords = useMemo(() => records.filter((record) => (zone === 'TODAS' || recordZone(record, locations) === zone) && (siembra === 'TODAS' || recordSiembra(record, locations) === siembra)), [records, zone, siembra, locations]);
  const selectedYear = rangeMode === 'ANUAL' ? year : period.slice(0, 4);
  const selectedRecords = useMemo(() => baseRecords.filter((record) => rangeMode === 'MENSUAL' ? record.period === period : record.period.startsWith(`${year}-`)), [baseRecords, rangeMode, period, year]);
  const comparisonRecords = useMemo(() => compareYear === 'SIN_COMPARACION' ? [] : baseRecords.filter((record) => record.period.startsWith(`${compareYear}-`)), [baseRecords, compareYear]);
  const summary = useMemo(() => metricSummary(selectedRecords, locations), [selectedRecords, locations]);
  const selectedLabel = rangeMode === 'MENSUAL' ? formatPeriod(period) : `Año ${year}`;

  const zoneData = useMemo(() => aggregate(selectedRecords, (record) => displayZoneName(recordZone(record, locations)), locations).sort((a, b) => b.tons - a.tons), [selectedRecords, locations]);
  const plantingData = useMemo(() => aggregate(selectedRecords, (record) => recordSiembra(record, locations), locations).sort((a, b) => Number(a.name) - Number(b.name)), [selectedRecords, locations]);
  const racimosByZone = useMemo(() => aggregate(selectedRecords, (record) => displayZoneName(recordZone(record, locations)), locations).sort((a, b) => b.racimos - a.racimos), [selectedRecords, locations]);
  const lotData = useMemo(() => aggregate(selectedRecords, (record) => record.loteCode, locations).sort((a, b) => b.tons - a.tons), [selectedRecords, locations]);
  const lotOptions = useMemo(() => Array.from(new Set(baseRecords.map((record) => record.loteCode))).sort(), [baseRecords]);
  useEffect(() => { if (lotOptions.length && (!selectedLot || !lotOptions.includes(selectedLot))) setSelectedLot(lotOptions[0]); }, [lotOptions, selectedLot]);

  const monthlyData = useMemo(() => MONTHS.map((name, index) => {
    const month = `${selectedYear}-${String(index + 1).padStart(2, '0')}`;
    const currentRows = baseRecords.filter((record) => record.period === month);
    const compareRows = compareYear === 'SIN_COMPARACION' ? [] : baseRecords.filter((record) => record.period === `${compareYear}-${String(index + 1).padStart(2, '0')}`);
    return { name, month, actual: currentRows.length ? metricSummary(currentRows, locations).tons : null, comparativo: compareRows.length ? metricSummary(compareRows, locations).tons : null };
  }), [baseRecords, selectedYear, compareYear, locations]);
  const cumulativeData = useMemo(() => { let actualTotal = 0; let comparisonTotal = 0; return monthlyData.map((item) => { if (item.actual !== null) actualTotal += item.actual; if (item.comparativo !== null) comparisonTotal += item.comparativo; return { ...item, acumulado: item.actual === null ? null : actualTotal, acumuladoComparativo: item.comparativo === null ? null : comparisonTotal }; }); }, [monthlyData]);
  const zoneTrendData = useMemo(() => MONTHS.map((name, index) => { const month = `${selectedYear}-${String(index + 1).padStart(2, '0')}`; return aggregate(baseRecords.filter((record) => record.period === month), (record) => displayZoneName(recordZone(record, locations)), locations).reduce<Record<string, any>>((entry, item) => ({ ...entry, [item.name]: item.tons }), { name }); }), [baseRecords, selectedYear, locations]);
  const comparisonByPlanting = useMemo(() => {
    const current = aggregate(baseRecords.filter((record) => record.period.startsWith(`${selectedYear}-`)), (record) => recordSiembra(record, locations), locations);
    const previous = compareYear === 'SIN_COMPARACION' ? [] : aggregate(comparisonRecords, (record) => recordSiembra(record, locations), locations);
    return Array.from(new Set([...current.map((item) => item.name), ...previous.map((item) => item.name)])).map((name) => ({ name, actual: current.find((item) => item.name === name)?.tons ?? null, comparativo: previous.find((item) => item.name === name)?.tons ?? null })).sort((a, b) => Number(a.name) - Number(b.name));
  }, [baseRecords, selectedYear, comparisonRecords, compareYear, locations]);
  const qualityVariation = useMemo(() => {
    const current = aggregate(baseRecords.filter((record) => record.period.startsWith(`${selectedYear}-`)), (record) => recordSiembra(record, locations), locations);
    const previous = compareYear === 'SIN_COMPARACION' ? [] : aggregate(comparisonRecords, (record) => recordSiembra(record, locations), locations);
    return current.map((item) => { const prior = previous.find((entry) => entry.name === item.name)?.averageWeight ?? null; return { name: item.name, actual: item.averageWeight, comparativo: prior, variacion: item.averageWeight !== null && prior ? ((item.averageWeight - prior) / prior) * 100 : null }; });
  }, [baseRecords, selectedYear, comparisonRecords, compareYear, locations]);
  const scatterWeight = useMemo(() => lotData.filter((item) => item.averageWeight !== null && item.tons > 0).map((item) => ({ lote: item.name, toneladas: item.tons, peso: item.averageWeight, hectareas: item.hectares || 1 })), [lotData]);
  const scatterEfficiency = useMemo(() => lotData.filter((item) => item.tonsPerHectare !== null && item.bunchesPerPalm !== null).map((item) => ({ lote: item.name, toneladasHa: item.tonsPerHectare, racimosPalma: item.bunchesPerPalm, hectareas: item.hectares || 1 })), [lotData]);
  const expectedLots = useMemo(() => (catalogs.locations || []).filter((location: any) => location.active !== false && (zone === 'TODAS' || location.zone === zone) && (siembra === 'TODAS' || String(location.anoSiembra ?? '') === siembra)).map((location: any) => normalizeLotCode(location.name)), [catalogs.locations, zone, siembra]);
  const coverageData = useMemo(() => { const expected = new Set(expectedLots); const registered = new Set(selectedRecords.map((record) => record.loteCode)); const total = expected.size || registered.size; const loaded = expected.size ? [...expected].filter((code) => registered.has(code)).length : registered.size; return [{ name: 'Con registro', value: loaded }, { name: 'Sin registro', value: Math.max(total - loaded, 0) }]; }, [expectedLots, selectedRecords]);
  const projectionScope = useMemo<{ scope: ProductivityProjectionScope; scopeValue: string }>(() => projectionFocus === 'LOTE' && selectedLot ? { scope: 'LOTE', scopeValue: selectedLot } : zone !== 'TODAS' ? { scope: 'ZONA', scopeValue: zone } : siembra !== 'TODAS' ? { scope: 'SIEMBRA', scopeValue: siembra } : { scope: 'GLOBAL', scopeValue: 'GLOBAL' }, [projectionFocus, selectedLot, zone, siembra]);
  const applicableProjections = useMemo(() => projections.filter((projection) => projection.scope === projectionScope.scope && projection.scopeValue === projectionScope.scopeValue), [projections, projectionScope]);
  const projectionRecords = useMemo(() => projectionFocus === 'LOTE' ? baseRecords.filter((record) => record.loteCode === selectedLot) : baseRecords, [projectionFocus, baseRecords, selectedLot]);
  const projectionMonthlyData = useMemo(() => MONTHS.map((name, index) => { const month = `${selectedYear}-${String(index + 1).padStart(2, '0')}`; const rows = projectionRecords.filter((record) => record.period === month); return { name, month, actual: rows.length ? metricSummary(rows, locations).tons : null }; }), [projectionRecords, selectedYear, locations]);
  const projectionData = useMemo(() => { let actualTotal = 0; let projectedTotal = 0; return projectionMonthlyData.map((item) => { const projected = applicableProjections.find((projection) => projection.period === item.month)?.projectedTons ?? null; if (item.actual !== null) actualTotal += item.actual; if (projected !== null) projectedTotal += projected; return { ...item, proyectado: projected, acumuladoReal: item.actual === null ? null : actualTotal, acumuladoProyectado: projected === null ? null : projectedTotal, desviacion: item.actual !== null && projected !== null ? item.actual - projected : null }; }); }, [projectionMonthlyData, applicableProjections]);
  const projectionSelectedRecords = useMemo(() => projectionRecords.filter((record) => rangeMode === 'MENSUAL' ? record.period === period : record.period.startsWith(`${year}-`)), [projectionRecords, rangeMode, period, year]);
  const projectionSummary = useMemo(() => metricSummary(projectionSelectedRecords, locations), [projectionSelectedRecords, locations]);
  const projectionTotal = projectionData.filter((item) => rangeMode === 'ANUAL' || item.month === period).reduce((sum, item) => sum + (item.proyectado || 0), 0);
  const projectionCompliance = projectionTotal ? (projectionSummary.tons / projectionTotal) * 100 : null;
  const lotHistory = useMemo(() => MONTHS.map((name, index) => ({ name, ...years.reduce<Record<string, number | null>>((result, itemYear) => { const rows = records.filter((record) => record.loteCode === selectedLot && record.period === `${itemYear}-${String(index + 1).padStart(2, '0')}`); result[itemYear] = rows.length ? metricSummary(rows, locations).tons : null; return result; }, {}) })), [records, selectedLot, years, locations]);
  const cycleRulesById = useMemo(() => new Map(cycleRules.map((rule) => [rule.id, rule])), [cycleRules]);
  const filteredCycleExecutions = useMemo(() => cycleExecutions.filter((execution) => {
    const executionPeriod = String(execution.executionDate || '').slice(0, 7);
    if (rangeMode === 'MENSUAL' ? executionPeriod !== period : !executionPeriod.startsWith(`${year}-`)) return false;
    const location = locations.get(normalizeLotCode(execution.loteCode));
    const executionZone = normalizeZoneName(location?.zone || 'Sin zona');
    const executionSiembra = location?.anoSiembra === null || location?.anoSiembra === undefined ? 'Sin siembra' : String(location.anoSiembra);
    return (zone === 'TODAS' || executionZone === zone) && (siembra === 'TODAS' || executionSiembra === siembra);
  }), [cycleExecutions, rangeMode, period, year, zone, siembra, locations]);
  const laborPerformance = useMemo(() => {
    const grouped = new Map<string, { name: string; workers: number; lots: Map<string, number> }>();
    filteredCycleExecutions.forEach((execution) => {
      const key = execution.laborCode;
      const entry = grouped.get(key) || { name: cycleRulesById.get(key)?.name || key, workers: 0, lots: new Map<string, number>() };
      entry.workers += Number(execution.personnelCount) || 0;
      const lotCode = normalizeLotCode(execution.loteCode);
      if (!entry.lots.has(lotCode)) entry.lots.set(lotCode, Number(locations.get(lotCode)?.ha) || 0);
      grouped.set(key, entry);
    });
    return Array.from(grouped.entries()).map(([id, entry]) => {
      const hectares = [...entry.lots.values()].reduce((sum, value) => sum + value, 0);
      const hectaresPerPerson = hectares > 0 && entry.workers > 0 ? hectares / entry.workers : null;
      return { id, name: entry.name, workers: entry.workers, lots: entry.lots.size, hectares, hectaresPerPerson, hectaresPerCrew: hectaresPerPerson === null ? null : hectaresPerPerson * 2 };
    }).sort((a, b) => (b.hectaresPerCrew || 0) - (a.hectaresPerCrew || 0));
  }, [filteredCycleExecutions, cycleRulesById, locations]);
  const harvestLots = useMemo(() => new Set(selectedRecords.map((record) => normalizeLotCode(record.loteCode))), [selectedRecords]);
  const harvestWorkers = useMemo(() => filteredCycleExecutions.filter((execution) => {
    const laborName = cycleRulesById.get(execution.laborCode)?.name || execution.laborCode;
    return normalizeZoneName(laborName) === 'COSECHA' && harvestLots.has(normalizeLotCode(execution.loteCode));
  }).reduce((sum, execution) => sum + (Number(execution.personnelCount) || 0), 0), [filteredCycleExecutions, cycleRulesById, harvestLots]);
  const tonsPerHarvestWorker = summary.tons > 0 && harvestWorkers > 0 ? summary.tons / harvestWorkers : null;
  const monthlyHarvestPerformance = useMemo(() => MONTHS.map((name, index) => {
    const itemPeriod = `${selectedYear}-${String(index + 1).padStart(2, '0')}`;
    const productivityRows = baseRecords.filter((record) => record.period === itemPeriod);
    const lotsWithProductivity = new Set(productivityRows.map((record) => normalizeLotCode(record.loteCode)));
    const workers = cycleExecutions.filter((execution) => {
      const laborName = cycleRulesById.get(execution.laborCode)?.name || execution.laborCode;
      return String(execution.executionDate || '').slice(0, 7) === itemPeriod && normalizeZoneName(laborName) === 'COSECHA' && lotsWithProductivity.has(normalizeLotCode(execution.loteCode));
    }).reduce((sum, execution) => sum + (Number(execution.personnelCount) || 0), 0);
    const tons = productivityRows.reduce((sum, record) => sum + tonsOf(record), 0);
    return { name, toneladasPorHombre: tons > 0 && workers > 0 ? tons / workers : null, toneladas: tons || null, personas: workers || null };
  }), [selectedYear, baseRecords, cycleExecutions, cycleRulesById]);
  const tabs: Array<{ id: View; label: string }> = [{ id: 'resumen', label: 'Resumen' }, { id: 'tendencias', label: 'Tendencias' }, { id: 'rendimiento', label: 'Rendimiento' }, { id: 'desempeno', label: 'Desempeño' }, { id: 'lotes', label: 'Lotes' }, { id: 'proyecciones', label: 'Metas y proyecciones' }];

  const handleFile = async (file?: File) => { if (!file) return; setNotice(null); try { setPreview({ ...(await parseProductivityFile(file)), file }); } catch { setNotice('No se pudo leer el archivo. Revisa la plantilla mensual de productividad.'); } };
  const confirmImport = async () => { if (!preview || !user) return; setImporting(true); const result = await repository.importProductivityRecords({ fileName: preview.file.name, fileType: preview.file.name.toLowerCase().endsWith('.csv') ? 'CSV' : 'XLSX', importedBy: user.id, rows: preview.rows, errors: preview.errors }); setImporting(false); if (result.ok) { setNotice(`Importación completada: ${preview.rows.length} registro(s) mensual(es).`); setPreview(null); } else setNotice(result.error || 'No fue posible guardar la importación. Verifica que la migración esté aplicada.'); };
  const saveManual = async (event: React.FormEvent) => { event.preventDefault(); const loteCode = normalizeLotCode(manual.loteCode); const location = locations.get(loteCode); if (!loteCode) return; if (![manual.racimos, manual.kilograms, manual.tons, manual.averageWeight].some((value) => value.trim())) { setNotice('Registra al menos un indicador de productividad antes de guardar.'); return; } setSaving(true); const result = await repository.saveProductivityRecord({ period: manual.period, loteCode, zonaSnapshot: location?.zone || null, siembraSnapshot: location?.anoSiembra ?? null, racimos: toNumberOrNull(manual.racimos), kilograms: toNumberOrNull(manual.kilograms), tons: toNumberOrNull(manual.tons), averageWeight: toNumberOrNull(manual.averageWeight) }); setSaving(false); if (result.ok) { setNotice(`Productividad de ${loteCode} guardada.`); setManualOpen(false); setManual({ period: currentPeriod(), loteCode: '', racimos: '', kilograms: '', tons: '', averageWeight: '' }); } else setNotice(result.error || 'No fue posible guardar el registro.'); };
  const saveProjection = async (event: React.FormEvent) => { event.preventDefault(); const projectedTons = toNumberOrNull(projectionForm.projectedTons); const scopeValue = projectionForm.scope === 'GLOBAL' ? 'GLOBAL' : projectionForm.scopeValue.trim(); if (projectedTons === null || projectedTons < 0 || !scopeValue) { setNotice('Completa el alcance y las toneladas proyectadas.'); return; } setSaving(true); const result = await repository.saveProductivityProjection({ period: projectionForm.period, scope: projectionForm.scope, scopeValue, projectedTons }); setSaving(false); if (result.ok) { setNotice(`Proyección de ${formatPeriod(projectionForm.period)} guardada.`); setProjectionOpen(false); setProjectionForm({ period: currentPeriod(), scope: 'GLOBAL', scopeValue: 'GLOBAL', projectedTons: '' }); } else setNotice(result.error || 'No fue posible guardar la proyección. Ejecuta la migración de proyecciones antes de intentarlo de nuevo.'); };

  if (loading) return <div className="min-h-[360px] flex flex-col items-center justify-center gap-3 text-forest-800"><Loader2 className="animate-spin" size={32} /><p className="text-sm font-medium">Cargando productividad…</p></div>;
  return <div className="space-y-5">
    <Card className="border-lime-300 bg-gradient-to-r from-lime-100 via-lime-50 to-white shadow-sm"><CardContent className="p-5 md:p-6 flex flex-col gap-5"><div className="flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between"><div><div className="flex items-center gap-2 text-forest-800 text-xs font-extrabold uppercase tracking-wider"><TrendingUp size={15} /> Análisis productivo</div><h2 className="text-2xl font-bold mt-1 text-forest-950">Productividad</h2><p className="text-sm text-gray-600 mt-1 max-w-2xl">Resumen mensual y anual por zona, siembra y lote. Los datos sin carga se muestran como faltantes, no como bajo rendimiento.</p></div><div className="flex flex-wrap gap-2">{user?.role === 'ADMIN' && <><Button onClick={() => setManualOpen(true)} variant="outline"><Plus size={16} className="mr-2" />Registrar mes</Button><Button onClick={() => setProjectionOpen(true)} variant="outline"><Target size={16} className="mr-2" />Registrar meta</Button><Button onClick={() => fileInputRef.current?.click()}><Upload size={16} className="mr-2" />Importar</Button><input ref={fileInputRef} className="hidden" type="file" accept=".xlsx,.xls,.csv" onChange={(event) => { handleFile(event.target.files?.[0]); event.currentTarget.value = ''; }} /></>}</div></div><div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-2 rounded-xl border border-lime-200 bg-white/80 p-3"><label className="text-xs font-semibold text-gray-600 flex flex-col gap-1"><span>Vista</span><select value={rangeMode} onChange={(event) => setRangeMode(event.target.value as RangeMode)} className="h-9 rounded-lg border border-gray-300 px-3 bg-white text-sm"><option value="MENSUAL">Mensual</option><option value="ANUAL">Anual</option></select></label>{rangeMode === 'MENSUAL' ? <label className="text-xs font-semibold text-gray-600 flex flex-col gap-1"><span>Periodo</span><Input type="month" value={period} onChange={(event) => { setPeriod(event.target.value); setYear(event.target.value.slice(0, 4)); }} className="h-9 bg-white" /></label> : <label className="text-xs font-semibold text-gray-600 flex flex-col gap-1"><span>Año</span><select value={year} onChange={(event) => setYear(event.target.value)} className="h-9 rounded-lg border border-gray-300 px-3 bg-white text-sm">{years.length ? years.map((item) => <option key={item} value={item}>{item}</option>) : <option value={year}>{year}</option>}</select></label>}<label className="text-xs font-semibold text-gray-600 flex flex-col gap-1"><span>Comparar con</span><select value={compareYear} onChange={(event) => setCompareYear(event.target.value)} className="h-9 rounded-lg border border-gray-300 px-3 bg-white text-sm"><option value="SIN_COMPARACION">Sin comparación</option>{years.filter((item) => item !== selectedYear).map((item) => <option key={item} value={item}>{item}</option>)}</select></label><label className="text-xs font-semibold text-gray-600 flex flex-col gap-1"><span>Zona</span><select value={zone} onChange={(event) => setZone(event.target.value)} className="h-9 rounded-lg border border-gray-300 px-3 bg-white text-sm"><option value="TODAS">Todas las zonas</option>{zones.map((item) => <option key={item} value={item}>{item}</option>)}</select></label><label className="text-xs font-semibold text-gray-600 flex flex-col gap-1"><span>Siembra</span><select value={siembra} onChange={(event) => setSiembra(event.target.value)} className="h-9 rounded-lg border border-gray-300 px-3 bg-white text-sm"><option value="TODAS">Todas las siembras</option>{siembras.map((item) => <option key={item} value={item}>{item}</option>)}</select></label></div></CardContent></Card>
    {notice && <div className="flex items-center justify-between rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-900"><span>{notice}</span><button onClick={() => setNotice(null)} aria-label="Cerrar aviso"><X size={16} /></button></div>}
    {preview && <Card className="border-blue-200 bg-blue-50/50"><CardContent className="p-4 md:p-5 flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div><p className="font-bold text-forest-950 flex items-center gap-2"><FileSpreadsheet size={18} className="text-blue-600" />Vista previa: {preview.file.name}</p><p className="text-sm text-gray-600 mt-1">{preview.rows.length} válidos de {preview.sourceRows} filas. {preview.errors.length} observación(es) no se importarán.</p>{preview.errors.length > 0 && <p className="text-xs text-red-700 mt-1">{preview.errors.slice(0, 2).join(' · ')}</p>}</div><div className="flex gap-2"><Button variant="outline" onClick={() => setPreview(null)}>Cancelar</Button><Button disabled={!preview.rows.length || importing} onClick={confirmImport}>{importing ? <Loader2 className="animate-spin mr-2" size={16} /> : <Upload className="mr-2" size={16} />}Confirmar carga</Button></div></CardContent></Card>}
    <div className="flex gap-1 overflow-x-auto border-b border-gray-200">{tabs.map((tab) => <button key={tab.id} onClick={() => setView(tab.id)} className={`px-4 py-2.5 text-sm font-bold whitespace-nowrap border-b-2 transition-colors ${view === tab.id ? 'border-forest-800 text-forest-950' : 'border-transparent text-gray-500 hover:text-forest-800'}`}>{tab.label}</button>)}</div>
    {view === 'resumen' && <SummaryView summary={summary} selectedLabel={selectedLabel} zoneData={zoneData} coverageData={coverageData} plantingData={plantingData} showCoverage={user?.role === 'ADMIN'} />}
    {view === 'tendencias' && <TrendsView monthlyData={monthlyData} cumulativeData={cumulativeData} zoneTrendData={zoneTrendData} zones={zones.map(displayZoneName)} zone={zone === 'TODAS' ? 'TODAS' : displayZoneName(zone)} comparisonByPlanting={comparisonByPlanting} selectedYear={selectedYear} compareYear={compareYear} />}
    {view === 'rendimiento' && <PerformanceView plantingData={plantingData} racimosByZone={racimosByZone} scatterWeight={scatterWeight} scatterEfficiency={scatterEfficiency} qualityVariation={qualityVariation} compareYear={compareYear} />}
    {view === 'desempeno' && <PerformanceDashboard selectedLabel={selectedLabel} selectedYear={selectedYear} laborPerformance={laborPerformance} tonsPerHarvestWorker={tonsPerHarvestWorker} harvestWorkers={harvestWorkers} monthlyHarvestPerformance={monthlyHarvestPerformance} />}
    {view === 'lotes' && <LotsView lotOptions={lotOptions} selectedLot={selectedLot} setSelectedLot={setSelectedLot} lotData={lotData} lotHistory={lotHistory} years={years} expectedLots={expectedLots} selectedLabel={selectedLabel} />}
    {view === 'proyecciones' && <ProjectionView summary={projectionSummary} projectionTotal={projectionTotal} projectionScope={projectionScope} projectionCompliance={projectionCompliance} applicableProjections={applicableProjections} projectionData={projectionData} userIsAdmin={user?.role === 'ADMIN'} projectionFocus={projectionFocus} setProjectionFocus={setProjectionFocus} selectedLot={selectedLot} setSelectedLot={setSelectedLot} lotOptions={lotOptions} />}
    {user?.role === 'ADMIN' && <DetailTable records={selectedRecords} annual={rangeMode === 'ANUAL'} locations={locations} />}
    {user?.role === 'ADMIN' && <ImportsCard imports={imports} />}
    <ManualDialog open={manualOpen} setOpen={setManualOpen} manual={manual} setManual={setManual} saving={saving} save={saveManual} />
    <ProjectionDialog open={projectionOpen} setOpen={setProjectionOpen} form={projectionForm} setForm={setProjectionForm} saving={saving} save={saveProjection} zones={zones} siembras={siembras} lots={lotOptions} />
  </div>;
}

function SummaryView({ summary, selectedLabel, zoneData, coverageData, plantingData, showCoverage }: any) { return <div className="space-y-5"><div className="grid grid-cols-2 lg:grid-cols-5 gap-3"><Metric label="Toneladas" value={numberFormatter.format(summary.tons)} suffix="t" note={selectedLabel} /><Metric label="Toneladas / ha" value={summary.tonsPerHectare === null ? '—' : numberFormatter.format(summary.tonsPerHectare)} suffix="t/ha" /><Metric label="Peso promedio" value={summary.averageWeight === null ? '—' : numberFormatter.format(summary.averageWeight)} suffix="kg/rac." /><Metric label="Racimos / palma" value={summary.bunchesPerPalm === null ? '—' : numberFormatter.format(summary.bunchesPerPalm)} suffix="rac./palma" /><Metric label="Lotes con registro" value={String(summary.lotCount)} suffix="lotes" /></div><div className={`grid grid-cols-1 ${showCoverage ? 'xl:grid-cols-2' : ''} gap-5`}><ChartCard title="Toneladas por zona" description={`Distribución para ${selectedLabel}.`}>{zoneData.length ? <ResponsiveContainer width="100%" height="100%"><BarChart data={zoneData} layout="vertical" margin={{ top: 10, right: 18, left: 12, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" horizontal={false} /><XAxis type="number" /><YAxis type="category" dataKey="name" width={88} tick={{ fontSize: 11 }} /><Tooltip /><Bar dataKey="tons" name="Toneladas" fill="#315D43" radius={[0, 6, 6, 0]} /></BarChart></ResponsiveContainer> : <Empty message="No hay productividad para este filtro." />}</ChartCard>{showCoverage && <ChartCard title="Cobertura de información" description="Lotes con producción cargada frente a los lotes activos del catálogo.">{coverageData.some((item: any) => item.value) ? <ResponsiveContainer width="100%" height="100%"><BarChart data={coverageData} margin={{ top: 24, right: 12, left: -15, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="name" tick={{ fontSize: 11 }} /><YAxis allowDecimals={false} /><Tooltip /><Bar dataKey="value" name="Lotes" radius={[6, 6, 0, 0]}>{coverageData.map((item: any) => <Cell key={item.name} fill={item.name === 'Con registro' ? '#315D43' : '#cbd5e1'} />)}</Bar></BarChart></ResponsiveContainer> : <Empty message="No hay lotes activos o registros para medir la cobertura." />}</ChartCard>}</div><ChartCard title="Toneladas por siembra" description="Resumen consolidado; no se replica una gráfica por cada siembra.">{plantingData.length ? <ResponsiveContainer width="100%" height="100%"><BarChart data={plantingData} margin={{ top: 10, right: 12, left: -15, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="name" tick={{ fontSize: 11 }} /><YAxis /><Tooltip /><Bar dataKey="tons" name="Toneladas" fill="#80a832" radius={[6, 6, 0, 0]} /></BarChart></ResponsiveContainer> : <Empty message="No hay datos para las siembras seleccionadas." />}</ChartCard></div>; }

function TrendsView({ monthlyData, cumulativeData, zoneTrendData, zones, zone, comparisonByPlanting, selectedYear, compareYear }: any) { return <div className="space-y-5"><div className="grid grid-cols-1 xl:grid-cols-2 gap-5"><ChartCard title="Producción por mes" description={`Año ${selectedYear}${compareYear === 'SIN_COMPARACION' ? '' : ` frente a ${compareYear}`}.`}><ResponsiveContainer width="100%" height="100%"><LineChart data={monthlyData} margin={{ top: 10, right: 18, left: -15, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="name" /><YAxis /><Tooltip /><Legend /><Line type="monotone" dataKey="actual" name={selectedYear} stroke="#315D43" strokeWidth={3} connectNulls={false} /><Line type="monotone" dataKey="comparativo" name={compareYear === 'SIN_COMPARACION' ? 'Sin comparación' : compareYear} stroke="#f59e0b" strokeWidth={2} strokeDasharray="6 4" hide={compareYear === 'SIN_COMPARACION'} /></LineChart></ResponsiveContainer></ChartCard><ChartCard title="Producción acumulada" description="Acumulado solo hasta los meses que tienen registro."><ResponsiveContainer width="100%" height="100%"><LineChart data={cumulativeData} margin={{ top: 10, right: 18, left: -15, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="name" /><YAxis /><Tooltip /><Legend /><Line type="monotone" dataKey="acumulado" name={`${selectedYear} acumulado`} stroke="#315D43" strokeWidth={3} connectNulls={false} /><Line type="monotone" dataKey="acumuladoComparativo" name={`${compareYear} acumulado`} stroke="#f59e0b" strokeWidth={2} strokeDasharray="6 4" hide={compareYear === 'SIN_COMPARACION'} /></LineChart></ResponsiveContainer></ChartCard></div><div className="grid grid-cols-1 xl:grid-cols-2 gap-5"><ChartCard title="Participación mensual por zona" description="La composición cambia mes a mes; puede enfocarse con el filtro de zona.">{zoneTrendData.some((row: any) => Object.keys(row).length > 1) ? <ResponsiveContainer width="100%" height="100%"><BarChart data={zoneTrendData} margin={{ top: 10, right: 18, left: -15, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="name" /><YAxis /><Tooltip /><Legend wrapperStyle={{ fontSize: 11 }} />{zones.filter((item: string) => zone === 'TODAS' || item === zone).map((item: string, index: number) => <Bar key={item} dataKey={item} stackId="zona" fill={PALETTE[index % PALETTE.length]} />)}</BarChart></ResponsiveContainer> : <Empty message="No hay registros mensuales para mostrar la participación." />}</ChartCard><ChartCard title="Comparativo por siembra" description="Toneladas anuales para los años seleccionados.">{comparisonByPlanting.length ? <ResponsiveContainer width="100%" height="100%"><BarChart data={comparisonByPlanting} margin={{ top: 10, right: 18, left: -15, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="name" tick={{ fontSize: 11 }} /><YAxis /><Tooltip /><Legend /><Bar dataKey="actual" name={selectedYear} fill="#315D43" radius={[5, 5, 0, 0]} /><Bar dataKey="comparativo" name={compareYear} fill="#f59e0b" radius={[5, 5, 0, 0]} hide={compareYear === 'SIN_COMPARACION'} /></BarChart></ResponsiveContainer> : <Empty message="No hay datos para comparar por siembra." />}</ChartCard></div></div>; }

function PerformanceView({ plantingData, racimosByZone, scatterWeight, scatterEfficiency, qualityVariation, compareYear }: any) { return <div className="space-y-5"><div className="grid grid-cols-1 xl:grid-cols-2 gap-5"><ChartCard title="Toneladas por hectárea por siembra" description="Toneladas consolidadas ÷ hectáreas de los lotes con registro.">{plantingData.some((item: any) => item.tonsPerHectare !== null) ? <ResponsiveContainer width="100%" height="100%"><BarChart data={plantingData} layout="vertical" margin={{ top: 10, right: 18, left: 12, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" horizontal={false} /><XAxis type="number" /><YAxis type="category" dataKey="name" width={88} /><Tooltip /><Bar dataKey="tonsPerHectare" name="t/ha" fill="#0f766e" radius={[0, 6, 6, 0]} /></BarChart></ResponsiveContainer> : <Empty message="Faltan hectáreas en Catálogos para calcular este indicador." />}</ChartCard><ChartCard title="Peso promedio del racimo por siembra" description="Calculado de forma ponderada con kilos y racimos.">{plantingData.some((item: any) => item.averageWeight !== null) ? <ResponsiveContainer width="100%" height="100%"><BarChart data={plantingData} margin={{ top: 10, right: 18, left: -15, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="name" tick={{ fontSize: 11 }} /><YAxis /><Tooltip /><Bar dataKey="averageWeight" name="kg/racimo" fill="#f59e0b" radius={[6, 6, 0, 0]} /></BarChart></ResponsiveContainer> : <Empty message="No hay kilos y racimos suficientes para calcular el peso." />}</ChartCard><ChartCard title="Racimos por palma por siembra" description="Racimos consolidados ÷ palmas totales del catálogo.">{plantingData.some((item: any) => item.bunchesPerPalm !== null) ? <ResponsiveContainer width="100%" height="100%"><BarChart data={plantingData} margin={{ top: 10, right: 18, left: -15, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="name" tick={{ fontSize: 11 }} /><YAxis /><Tooltip /><Bar dataKey="bunchesPerPalm" name="racimos/palma" fill="#7c3aed" radius={[6, 6, 0, 0]} /></BarChart></ResponsiveContainer> : <Empty message="Faltan palmas totales en Catálogos para calcular este indicador." />}</ChartCard><ChartCard title="Racimos por zona" description="Volumen de racimos del período seleccionado.">{racimosByZone.length ? <ResponsiveContainer width="100%" height="100%"><BarChart data={racimosByZone} margin={{ top: 10, right: 18, left: -15, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="name" tick={{ fontSize: 11 }} /><YAxis /><Tooltip /><Bar dataKey="racimos" name="Racimos" fill="#80a832" radius={[6, 6, 0, 0]} /></BarChart></ResponsiveContainer> : <Empty message="No hay racimos para este filtro." />}</ChartCard></div><div className="grid grid-cols-1 xl:grid-cols-2 gap-5"><ChartCard title="Peso del racimo vs. toneladas por lote" description="Identifica la relación entre calidad y volumen.">{scatterWeight.length ? <ResponsiveContainer width="100%" height="100%"><ScatterChart margin={{ top: 10, right: 18, left: 0, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" /><XAxis type="number" dataKey="peso" name="Peso" unit=" kg" /><YAxis type="number" dataKey="toneladas" name="Toneladas" unit=" t" /><ZAxis type="number" dataKey="hectareas" range={[50, 260]} name="Hectáreas" /><Tooltip cursor={{ strokeDasharray: '3 3' }} formatter={(value: number, name) => [numberFormatter.format(value), name]} labelFormatter={(_, rows: any[]) => rows?.[0]?.payload?.lote || ''} /><Scatter name="Lotes" data={scatterWeight} fill="#315D43" /></ScatterChart></ResponsiveContainer> : <Empty message="Se necesitan toneladas y peso promedio por lote." />}</ChartCard><ChartCard title="Racimos por palma vs. toneladas/ha" description="Comparación de eficiencia entre lotes.">{scatterEfficiency.length ? <ResponsiveContainer width="100%" height="100%"><ScatterChart margin={{ top: 10, right: 18, left: 0, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" /><XAxis type="number" dataKey="racimosPalma" name="Racimos/palma" /><YAxis type="number" dataKey="toneladasHa" name="Toneladas/ha" /><ZAxis type="number" dataKey="hectareas" range={[50, 260]} name="Hectáreas" /><Tooltip cursor={{ strokeDasharray: '3 3' }} formatter={(value: number, name) => [numberFormatter.format(value), name]} labelFormatter={(_, rows: any[]) => rows?.[0]?.payload?.lote || ''} /><Scatter name="Lotes" data={scatterEfficiency} fill="#0f766e" /></ScatterChart></ResponsiveContainer> : <Empty message="Se necesitan hectáreas, palmas totales y racimos en el catálogo y registros." />}</ChartCard></div>{compareYear !== 'SIN_COMPARACION' && <ChartCard title="Variación del peso promedio frente al año comparado" description="Cambio porcentual por siembra.">{qualityVariation.length ? <ResponsiveContainer width="100%" height="100%"><BarChart data={qualityVariation} margin={{ top: 10, right: 18, left: -15, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="name" /><YAxis unit="%" /><Tooltip formatter={(value: number) => [`${percentageFormatter.format(value)}%`, 'Variación']} /><Bar dataKey="variacion" name="Variación" radius={[5, 5, 0, 0]}>{qualityVariation.map((item: any) => <Cell key={item.name} fill={(item.variacion || 0) >= 0 ? '#315D43' : '#dc2626'} />)}</Bar></BarChart></ResponsiveContainer> : <Empty message="No hay pesos promedio comparables." />}</ChartCard>}</div>; }

function PerformanceDashboard({ selectedLabel, selectedYear, laborPerformance, tonsPerHarvestWorker, harvestWorkers, monthlyHarvestPerformance }: any) {
  const measuredLabors = laborPerformance.filter((item: any) => item.hectaresPerCrew !== null);
  const coveredHectares = laborPerformance.reduce((sum: number, item: any) => sum + item.hectares, 0);
  const registeredPeople = laborPerformance.reduce((sum: number, item: any) => sum + item.workers, 0);
  return <div className="space-y-5">
    <Card className="border-forest-100 bg-forest-50/40">
      <CardContent className="p-4 md:p-5">
        <p className="font-bold text-forest-950">Desempeño operativo</p>
        <p className="mt-1 text-sm text-gray-600">Recorrido de cuadrilla y productividad de cosecha para {selectedLabel}. Cada cuadrilla equivale a 2 personas, como en el Control de Labores.</p>
      </CardContent>
    </Card>
    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
      <Metric label="Toneladas por jornal" value={tonsPerHarvestWorker === null ? '—' : numberFormatter.format(tonsPerHarvestWorker)} suffix="t/jornal" note="Solo cosecha" />
      <Metric label="Jornales en cosecha" value={numberFormatter.format(harvestWorkers)} suffix="jornales" note="Con lote y producción del período" />
      <Metric label="Hectáreas intervenidas" value={numberFormatter.format(coveredHectares)} suffix="ha" note="Lotes únicos por labor" />
      <Metric label="Personas registradas" value={numberFormatter.format(registeredPeople)} suffix="personas" note="Todas las labores" />
    </div>
    <div className="grid grid-cols-1 xl:grid-cols-2 gap-5">
      <ChartCard title="Rendimiento por labor" description="Hectáreas netas de lotes intervenidos ÷ personas registradas para cada labor.">
        {measuredLabors.length ? <ResponsiveContainer width="100%" height="100%"><BarChart data={measuredLabors} layout="vertical" margin={{ top: 10, right: 24, left: 14, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" horizontal={false} /><XAxis type="number" /><YAxis type="category" dataKey="name" width={118} tick={{ fontSize: 11 }} /><Tooltip formatter={(value: number, name: string) => [numberFormatter.format(value), name]} /><Bar dataKey="hectaresPerPerson" name="ha/hombre" fill="#315D43" radius={[0, 6, 6, 0]} /></BarChart></ResponsiveContainer> : <Empty message="Faltan ejecuciones con personal y hectáreas de lote para calcular el rendimiento." />}
      </ChartCard>
      <ChartCard title="Recorrido por cuadrilla" description="Hectáreas netas de lotes intervenidos ÷ personas registradas × 2 personas por cuadrilla.">
        {measuredLabors.length ? <ResponsiveContainer width="100%" height="100%"><BarChart data={measuredLabors} layout="vertical" margin={{ top: 10, right: 24, left: 14, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" horizontal={false} /><XAxis type="number" /><YAxis type="category" dataKey="name" width={118} tick={{ fontSize: 11 }} /><Tooltip formatter={(value: number, name: string) => [numberFormatter.format(value), name]} /><Bar dataKey="hectaresPerCrew" name="ha/cuadrilla" fill="#0f766e" radius={[0, 6, 6, 0]} /></BarChart></ResponsiveContainer> : <Empty message="Faltan ejecuciones con personal y hectáreas de lote para calcular el recorrido." />}
      </ChartCard>
      <ChartCard title="Toneladas por jornal en cosecha" description={`Toneladas cargadas ÷ jornales de cosecha en los mismos lotes, por mes de ${selectedYear}.`} className="xl:col-span-2">
        {monthlyHarvestPerformance.some((item: any) => item.toneladasPorHombre !== null) ? <ResponsiveContainer width="100%" height="100%"><ComposedChart data={monthlyHarvestPerformance} margin={{ top: 10, right: 18, left: -15, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="name" /><YAxis yAxisId="left" /><YAxis yAxisId="right" orientation="right" /><Tooltip formatter={(value: number, name: string) => [numberFormatter.format(value), name]} /><Legend /><Bar yAxisId="left" dataKey="toneladasPorHombre" name="t/jornal" fill="#f59e0b" radius={[6, 6, 0, 0]} /><Line yAxisId="right" type="monotone" dataKey="personas" name="Jornales" stroke="#315D43" strokeWidth={2.5} connectNulls={false} /></ComposedChart></ResponsiveContainer> : <Empty message="Faltan toneladas de productividad o jornales registrados en cosecha para calcular este indicador." />}
      </ChartCard>
    </div>
  </div>;
}

function LotsView({ lotOptions, selectedLot, setSelectedLot, lotData, lotHistory, years, expectedLots, selectedLabel }: any) { return <div className="space-y-5"><Card className="border-forest-100"><CardContent className="p-4 flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-bold text-sm text-forest-950">Análisis histórico por lote</p><p className="text-xs text-gray-500">El ranking considera únicamente lotes con datos; los faltantes se muestran por separado.</p></div><label className="text-xs font-bold text-gray-600 flex items-center gap-2">Lote<select value={selectedLot} onChange={(event) => setSelectedLot(event.target.value)} className="h-9 min-w-40 rounded-lg border border-gray-300 px-3 text-sm text-forest-950 bg-white">{lotOptions.map((item: string) => <option key={item} value={item}>{item}</option>)}</select></label></CardContent></Card><div className="grid grid-cols-1 xl:grid-cols-2 gap-5"><ChartCard title="Lotes más productivos" description={`Top 10 por toneladas · ${selectedLabel}.`}>{lotData.length ? <ResponsiveContainer width="100%" height="100%"><BarChart data={lotData.slice(0, 10)} layout="vertical" margin={{ top: 10, right: 18, left: 16, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" horizontal={false} /><XAxis type="number" /><YAxis type="category" dataKey="name" width={82} tick={{ fontSize: 11 }} /><Tooltip /><Bar dataKey="tons" name="Toneladas" fill="#315D43" radius={[0, 6, 6, 0]} /></BarChart></ResponsiveContainer> : <Empty message="No hay lotes con producción registrada." />}</ChartCard><ChartCard title="Lotes con menor producción registrada" description="No incluye lotes sin datos para evitar alertas incorrectas.">{lotData.length ? <ResponsiveContainer width="100%" height="100%"><BarChart data={[...lotData].reverse().slice(0, 10)} layout="vertical" margin={{ top: 10, right: 18, left: 16, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" horizontal={false} /><XAxis type="number" /><YAxis type="category" dataKey="name" width={82} tick={{ fontSize: 11 }} /><Tooltip /><Bar dataKey="tons" name="Toneladas" fill="#f59e0b" radius={[0, 6, 6, 0]} /></BarChart></ResponsiveContainer> : <Empty message="No hay lotes con producción registrada." />}</ChartCard></div><ChartCard title={`Histórico de ${selectedLot || 'lote'}`} description="Toneladas mensuales por año importado.">{selectedLot ? <ResponsiveContainer width="100%" height="100%"><LineChart data={lotHistory} margin={{ top: 10, right: 18, left: -15, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="name" /><YAxis /><Tooltip /><Legend />{years.map((item: string, index: number) => <Line key={item} type="monotone" dataKey={item} name={item} stroke={PALETTE[index % PALETTE.length]} strokeWidth={2.5} connectNulls={false} />)}</LineChart></ResponsiveContainer> : <Empty message="Selecciona un lote con historial." />}</ChartCard><Card><CardHeader className="pb-2"><CardTitle className="text-base text-forest-950">Mapa de calor por lote</CardTitle><p className="text-xs text-gray-500 mt-1">La intensidad representa toneladas. “Sin dato” no es una clasificación de rendimiento.</p></CardHeader><CardContent><LotHeatmap data={lotData} expectedLots={expectedLots} /></CardContent></Card></div>; }

function ProjectionView({ summary, projectionTotal, projectionScope, projectionCompliance, applicableProjections, projectionData, userIsAdmin, projectionFocus, setProjectionFocus, selectedLot, setSelectedLot, lotOptions }: any) { return <div className="space-y-5"><Card className="border-forest-100"><CardContent className="p-4 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-bold text-sm text-forest-950">Alcance de la meta</p><p className="text-xs text-gray-500">Usa los filtros globales o revisa la proyección específica de un lote.</p></div><div className="flex flex-col sm:flex-row gap-2"><select value={projectionFocus} onChange={(event) => setProjectionFocus(event.target.value)} className="h-9 rounded-lg border border-gray-300 px-3 text-sm text-forest-950 bg-white"><option value="FILTROS">Según filtros</option><option value="LOTE">Por lote</option></select>{projectionFocus === 'LOTE' && <select value={selectedLot} onChange={(event) => setSelectedLot(event.target.value)} className="h-9 min-w-36 rounded-lg border border-gray-300 px-3 text-sm text-forest-950 bg-white">{lotOptions.map((item: string) => <option key={item} value={item}>{item}</option>)}</select>}</div></CardContent></Card><div className="grid grid-cols-1 sm:grid-cols-3 gap-3"><Metric label="Producción real" value={numberFormatter.format(summary.tons)} suffix="t" /><Metric label="Meta registrada" value={projectionTotal ? numberFormatter.format(projectionTotal) : '—'} suffix="t" note={`${projectionScope.scope.toLowerCase()}: ${projectionScope.scopeValue}`} /><Metric label="Cumplimiento" value={projectionCompliance === null ? '—' : numberFormatter.format(projectionCompliance)} suffix="%" note="Real frente a meta del mismo alcance" /></div>{!applicableProjections.length && <div className="rounded-xl border border-blue-200 bg-blue-50 px-4 py-3 text-sm text-blue-900">Aún no hay metas para este alcance. {userIsAdmin ? 'Usa “Registrar meta” para cargar una proyección mensual.' : 'El administrador puede registrar una proyección mensual.'}</div>}<div className="grid grid-cols-1 xl:grid-cols-2 gap-5"><ChartCard title="Producción real vs. meta mensual" description="Barras de producción real y línea de toneladas proyectadas."><ResponsiveContainer width="100%" height="100%"><ComposedChart data={projectionData} margin={{ top: 10, right: 18, left: -15, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="name" /><YAxis /><Tooltip /><Legend /><Bar dataKey="actual" name="Real" fill="#315D43" radius={[5, 5, 0, 0]} /><Line type="monotone" dataKey="proyectado" name="Meta" stroke="#f59e0b" strokeWidth={3} connectNulls={false} /></ComposedChart></ResponsiveContainer></ChartCard><ChartCard title="Acumulado real vs. meta" description="Seguimiento anual del cumplimiento."><ResponsiveContainer width="100%" height="100%"><LineChart data={projectionData} margin={{ top: 10, right: 18, left: -15, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="name" /><YAxis /><Tooltip /><Legend /><Line type="monotone" dataKey="acumuladoReal" name="Real acumulado" stroke="#315D43" strokeWidth={3} connectNulls={false} /><Line type="monotone" dataKey="acumuladoProyectado" name="Meta acumulada" stroke="#f59e0b" strokeWidth={3} strokeDasharray="6 4" connectNulls={false} /></LineChart></ResponsiveContainer></ChartCard></div><ChartCard title="Desviación real frente a la meta" description="Verde: sobre la meta. Rojo: por debajo de la meta."><ResponsiveContainer width="100%" height="100%"><BarChart data={projectionData} margin={{ top: 10, right: 18, left: -15, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="name" /><YAxis /><Tooltip /><Bar dataKey="desviacion" name="Desviación" radius={[5, 5, 0, 0]}>{projectionData.map((item: any) => <Cell key={item.name} fill={(item.desviacion || 0) >= 0 ? '#315D43' : '#dc2626'} />)}</Bar></BarChart></ResponsiveContainer></ChartCard></div>; }

function DetailTable({ records, annual, locations }: { records: ProductivityRecord[]; annual: boolean; locations: Map<string, any> }) { return <Card><CardHeader className="pb-2"><CardTitle className="text-base text-forest-950">Detalle {annual ? 'anual por registros mensuales' : 'mensual'}</CardTitle><p className="text-xs text-gray-500">Se conserva el detalle fuente para revisar cualquier gráfico.</p></CardHeader><CardContent><div className="overflow-auto rounded-xl border"><table className="w-full min-w-[860px] text-sm"><thead className="bg-gray-50 text-xs uppercase text-gray-500"><tr>{annual && <th className="text-left p-3">Periodo</th>}<th className="text-left p-3">Lote</th><th className="text-left p-3">Zona</th><th className="text-left p-3">Siembra</th><th className="text-right p-3">Racimos</th><th className="text-right p-3">Kilos</th><th className="text-right p-3">Toneladas</th><th className="text-right p-3">Peso promedio</th><th className="text-left p-3">Origen</th></tr></thead><tbody>{records.map((record) => <tr key={record.id} className="border-t border-gray-100">{annual && <td className="p-3 text-gray-500">{formatPeriod(record.period)}</td>}<td className="p-3 font-bold text-forest-950">{record.loteCode}</td><td className="p-3 text-gray-500">{recordZone(record, locations)}</td><td className="p-3 text-gray-500">{recordSiembra(record, locations)}</td><td className="p-3 text-right font-mono">{record.racimos === null ? '—' : numberFormatter.format(record.racimos)}</td><td className="p-3 text-right font-mono">{record.kilograms === null ? '—' : numberFormatter.format(record.kilograms)}</td><td className="p-3 text-right font-mono">{numberFormatter.format(tonsOf(record))}</td><td className="p-3 text-right font-mono">{record.averageWeight === null ? '—' : numberFormatter.format(record.averageWeight)}</td><td className="p-3"><span className={`rounded-full px-2 py-0.5 text-[10px] font-black border ${record.source === 'MANUAL' ? 'bg-amber-50 border-amber-200 text-amber-800' : 'bg-blue-50 border-blue-200 text-blue-800'}`}>{record.source === 'MANUAL' ? 'Manual' : 'Importación'}</span></td></tr>)}{!records.length && <tr><td colSpan={annual ? 10 : 9} className="p-12 text-center text-gray-500">No hay productividad registrada para este filtro.</td></tr>}</tbody></table></div></CardContent></Card>; }

function ImportsCard({ imports }: { imports: ProductivityImport[] }) { return <Card><CardHeader className="pb-2"><CardTitle className="text-base text-forest-950">Últimas cargas</CardTitle></CardHeader><CardContent><div className="space-y-2 max-h-[260px] overflow-y-auto">{imports.length ? imports.map((item) => <div key={item.id} className="rounded-lg border border-gray-100 bg-gray-50 p-3"><p className="font-bold text-xs text-forest-950 truncate">{item.fileName}</p><p className="text-[11px] text-gray-500 mt-1">{item.acceptedRows} registros · {new Date(item.importedAt).toLocaleDateString('es-CO')}</p></div>) : <Empty message="Aún no hay importaciones." />}</div></CardContent></Card>; }
function ManualDialog({ open, setOpen, manual, setManual, saving, save }: any) { return <Dialog open={open} onOpenChange={setOpen}><DialogContent className="sm:max-w-xl"><DialogHeader><DialogTitle>Registrar productividad mensual</DialogTitle><DialogDescription>La zona y siembra se completan desde el lote cuando exista en el catálogo.</DialogDescription></DialogHeader><form onSubmit={save} className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-2"><Field label="Periodo"><Input type="month" required value={manual.period} onChange={(event) => setManual({ ...manual, period: event.target.value })} /></Field><Field label="Lote"><Input required placeholder="Ej. 09E007" value={manual.loteCode} onChange={(event) => setManual({ ...manual, loteCode: event.target.value })} /></Field><Field label="Racimos"><Input inputMode="decimal" value={manual.racimos} onChange={(event) => setManual({ ...manual, racimos: event.target.value })} /></Field><Field label="Kilogramos"><Input inputMode="decimal" value={manual.kilograms} onChange={(event) => setManual({ ...manual, kilograms: event.target.value })} /></Field><Field label="Toneladas"><Input inputMode="decimal" value={manual.tons} onChange={(event) => setManual({ ...manual, tons: event.target.value })} /></Field><Field label="Peso promedio"><Input inputMode="decimal" value={manual.averageWeight} onChange={(event) => setManual({ ...manual, averageWeight: event.target.value })} /></Field><div className="sm:col-span-2 flex justify-end gap-2 pt-2"><Button type="button" variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={saving} type="submit">{saving && <Loader2 className="mr-2 animate-spin" size={16} />}Guardar registro</Button></div></form></DialogContent></Dialog>; }
function ProjectionDialog({ open, setOpen, form, setForm, saving, save, zones, siembras, lots }: any) { const options = form.scope === 'ZONA' ? zones : form.scope === 'SIEMBRA' ? siembras : lots; return <Dialog open={open} onOpenChange={setOpen}><DialogContent className="sm:max-w-lg"><DialogHeader><DialogTitle>Registrar meta mensual</DialogTitle><DialogDescription>Guarda la meta en toneladas para toda la empresa, una zona, una siembra o un lote. Las metas no alteran los registros reales.</DialogDescription></DialogHeader><form onSubmit={save} className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-2"><Field label="Periodo"><Input type="month" required value={form.period} onChange={(event) => setForm({ ...form, period: event.target.value })} /></Field><Field label="Alcance"><select value={form.scope} onChange={(event) => { const scope = event.target.value as ProductivityProjectionScope; setForm({ ...form, scope, scopeValue: scope === 'GLOBAL' ? 'GLOBAL' : '' }); }} className="h-10 w-full rounded-lg border border-gray-300 px-3 text-sm"><option value="GLOBAL">Empresa completa</option><option value="ZONA">Zona</option><option value="SIEMBRA">Siembra</option><option value="LOTE">Lote</option></select></Field>{form.scope !== 'GLOBAL' && <Field label={form.scope === 'ZONA' ? 'Zona' : form.scope === 'SIEMBRA' ? 'Siembra' : 'Lote'}><select required value={form.scopeValue} onChange={(event) => setForm({ ...form, scopeValue: event.target.value })} className="h-10 w-full rounded-lg border border-gray-300 px-3 text-sm"><option value="">Selecciona…</option>{options.map((item: string) => <option key={item} value={item}>{item}</option>)}</select></Field>}<Field label="Toneladas proyectadas"><Input required min="0" inputMode="decimal" placeholder="Ej. 1646" value={form.projectedTons} onChange={(event) => setForm({ ...form, projectedTons: event.target.value })} /></Field><div className="sm:col-span-2 flex justify-end gap-2 pt-2"><Button type="button" variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={saving} type="submit">{saving && <Loader2 className="mr-2 animate-spin" size={16} />}Guardar meta</Button></div></form></DialogContent></Dialog>; }
function LotHeatmap({ data, expectedLots }: { data: Array<{ name: string; tons: number }>; expectedLots: string[] }) { const byLot = new Map(data.map((item) => [item.name, item.tons])); const lots = expectedLots.length ? expectedLots : data.map((item) => item.name); const max = Math.max(...data.map((item) => item.tons), 0); if (!lots.length) return <Empty message="No hay lotes para representar." />; return <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 xl:grid-cols-6 gap-2">{lots.map((lot) => { const tons = byLot.get(lot); const intensity = tons === undefined || !max ? 0 : Math.max(.15, tons / max); return <div key={lot} className="rounded-lg border p-3" style={tons === undefined ? { backgroundColor: '#f8fafc', borderColor: '#e2e8f0' } : { backgroundColor: `rgba(49, 93, 67, ${intensity})`, borderColor: 'rgba(49, 93, 67, .4)' }}><p className={`font-black text-sm ${tons === undefined ? 'text-slate-600' : intensity > .48 ? 'text-white' : 'text-forest-950'}`}>{lot}</p><p className={`text-xs mt-1 ${tons === undefined ? 'text-slate-400' : intensity > .48 ? 'text-white/85' : 'text-forest-800'}`}>{tons === undefined ? 'Sin dato' : `${numberFormatter.format(tons)} t`}</p></div>; })}</div>; }
